const _kCueEn = <String, String>{
  // ===== 2026-09-27 补齐全部动作要点后的配套英译（105 条主库 + 36 条第三弹） =====
  '杠铃卧推': 'Lie back with shoulder blades pinched and feet planted; lower the bar to the mid-lower chest with forearms vertical, press up to just short of lockout. Common mistakes: shoulder blades coming loose and shrugging, the bar drifting toward the neck, feet leaving the floor.',
  '上斜杠铃卧推': 'Set the incline around 30 degrees; keep the shoulder blades tight and down, lower the bar just above the collarbone, press with elbows tucked slightly in. Common mistakes: a bench set too steep turning it into a shoulder press, bouncing off the collarbone.',
  '上斜哑铃卧推': 'Back firm against the incline bench; press the dumbbells from chest sides in an arc until they nearly touch, lower until the upper arms reach or just pass parallel for a full upper-chest stretch. Common mistakes: elbows flaring so the front delts take over, cutting the descent short.',
  '哑铃卧推': 'Lie back with shoulder blades pinched; dumbbells at mid-chest sides, press straight up without clanging them at the top. Common mistakes: shoulder blades loosening, drifting into a narrow tucked-elbow press.',
  '坐姿夹胸（蝴蝶机）': 'Set the seat so the handles sit at chest height; keep a fixed slight elbow bend and squeeze the handles together with the pecs, holding one second at full contraction. Common mistakes: loading so heavy you pry with the arms, shrugging for leverage.',
  '绳索夹胸': 'Set the pulleys high or at chest height; lean forward with a stable stance and a fixed slight elbow bend, then sweep the handles down and together in front of you. Common mistakes: bending the elbows into an arm movement, swinging the torso.',
  '双杠臂屈伸（挺胸）': 'Support yourself on the bars and lean the torso forward with the chest proud; bend the elbows until the chest stretches, then press up. More forward lean shifts work to the chest; a more upright body hits the triceps. Common mistakes: shrugging and caving the chest, dipping too deep and loading the shoulders.',
  '俯卧撑': 'Hands slightly wider than the shoulders, one line from head to heels; bend the elbows to bring the chest near the floor and press back up. Common mistakes: sagging or piked hips, the head diving first, arms flaring into a T that overloads the shoulders.',
  '上斜俯卧撑': 'Hands on a bench or step, feet on the floor; keep the body in one line as you perform the push-up. The higher the support, the easier it gets - the stepping stone toward floor push-ups. Common mistakes: sagging hips, lowering only the head while the chest stays high.',
  '下斜俯卧撑（脚垫高）': 'Feet up on a bench, hands on the floor; the forward-shifted load targets the upper chest and front delts while the body stays in one line. Common mistakes: sagging hips, driving the head toward the floor.',
  '上斜杠铃卧推（轻）': 'Same setup as the incline press with a light weight for higher reps; groove the bar path and upper-chest feel, lowering under control for 2-3 seconds. Common mistakes: rushing with bottom bounces, an inconsistent path.',
  '哑铃飞鸟': 'Lie flat with a fixed slight elbow bend; open the dumbbells in an arc until the chest fully stretches, then close them as if hugging a large barrel. Common mistakes: the elbow angle changing into a press, dropping too deep and jamming the shoulders.',
  '弹力带夹胸': 'Loop the band around the upper back or anchor it behind at chest-to-high level; keep a fixed slight elbow bend and sweep the hands forward and together until they touch. Common mistakes: bending the elbows into an arm movement, leaning back for leverage.',
  '引体向上': 'Overhand grip slightly wider than the shoulders; start by depressing the shoulder blades, then pull the chest toward the bar until the chin clears it. Common mistakes: pulling only with the arms without the scapula, kicking and swinging.',
  '负重引体向上': 'Hang a plate from a belt or hold it between the legs; the path matches the bodyweight pull-up. Pick a load you can control for 5-8 clean reps. Common mistakes: load wrecking the technique, free-falling on the way down.',
  '高位下拉': 'Thighs locked under the pads; take a wide overhand grip, pull the shoulder blades down and back first, then drive the bar to the upper chest with the elbows pointing straight down. Common mistakes: leaning far back into a row, pulling with the biceps.',
  '杠铃划船': 'Hinge to about 45 degrees with a flat back; drag the bar along the thighs to the lower belly with the elbows skimming the sides. Common mistakes: rounding the back, standing up to heave the bar, pulling to the chest and turning it into a rear-delt move.',
  '坐姿划船': 'Brace against the foot plate with a tall chest; pull the handle to the belly with the elbows close and squeeze the back for one second at the finish. Common mistakes: rocking the torso back and forth, shrugging.',
  '杠铃硬拉': 'Bar against the shins; hinge down and grip with a flat back and proud chest, then drive through the heels to stand with the bar dragging the body, finishing with the glutes locked. Common mistakes: rounding the back, the bar drifting away so the lower back carries it, overextending at the top.',
  '直臂下压': 'A slight forward lean with the elbows locked in a gentle bend; pull the cable from up front down to your sides using the lats. Common mistakes: bending the elbows into a triceps pushdown, swinging the torso.',
  'T杠划船': 'Straddle or stand over the bar with the chest facing forward and the back flat; pull the handle toward the chest-belly line with the elbows tight. Common mistakes: rounding the back, heaving with momentum.',
  '哑铃单臂划船': 'One hand and one knee on the bench, back parallel to the floor; drag the dumbbell to the hip with the elbow brushing the ribs. Common mistakes: twisting the torso for leverage, pulling to the chest and making it a rear-delt move.',
  '弹力带下拉': 'Anchor the band overhead (door anchor or pull-up bar); kneel or sit, depress the shoulder blades and pull the band to the collarbone, mimicking the lat pulldown. Common mistakes: leaning back, bending the elbows without engaging the back.',
  '弹力带坐姿划船': 'Loop the band around the feet with the legs extended; sit tall and pull to the belly with the elbows close. Common mistakes: rounding the back, swinging the torso.',
  '超人式': 'Lie prone and raise the arms and legs together; contract the lower back and glutes, hold 1-2 seconds at the top, lower slowly. Common mistakes: craning the neck, bouncing too high off the lower back.',
  '反向雪天使': 'Lie prone with the forehead lightly down, arms alongside and palms up; slide the arms along the floor in a half-circle overhead into a Y and back, never letting them leave the floor. Common mistakes: shrugging, flying the arms up into a different movement.',
  '站姿推举': 'Start with the bar at the collarbone, brace the core and glutes, and press straight overhead until the bar sits over the ears, the head slightly back so the bar travels a straight line. Common mistakes: over-arching the lower back, looping the bar far from the face, holding the breath throughout.',
  '坐姿哑铃推举': 'Seated with back support, dumbbells at ear height and elbows slightly in front of the torso; press up until they nearly meet. Common mistakes: the lower back peeling off into a bridge, pressing behind the head.',
  '史密斯机推肩': 'Sit under the Smith bar landing at chin height and press straight up along the rail; with balance already fixed, deliberately slow the lowering phase. Common mistakes: ducking the torso forward to dodge the bar, launching off the bottom.',
  '哑铃侧平举': 'Arms hanging with a slight elbow bend; raise the dumbbells out to the sides to shoulder height with the elbow, wrist and hand in one plane. Common mistakes: shrugging into an upright row, swinging, raising too high.',
  '俯身飞鸟（后束）': 'Hinge until the upper back is near parallel with a slight elbow bend; open the dumbbells out to the sides with the rear delts, thumbs down. Common mistakes: standing up rep by rep, the lats rowing instead.',
  '面拉': 'Set the rope at face height; pull toward the forehead with a neutral grip while rotating externally so the arms form two L shapes, and pause one second. Common mistakes: pulling to the chest, shrugging.',
  '哑铃前平举': 'A slight elbow bend; raise the dumbbells straight ahead to shoulder height, alternating sides if you like. Common mistakes: swinging the lower back, raising past the head.',
  '杠铃耸肩': 'Arms locked straight; shrug the shoulders straight up toward the ears, hold one second at the top, lower slowly. Common mistakes: rolling the shoulders (harsh on the joints), bending the elbows to haul.',
  '弹力带侧平举': 'Stand on the band and raise out to the sides like the dumbbell version; band tension peaks at the top so lower slowly. Common mistakes: leaning sideways for leverage, shrugging.',
  '派克俯卧撑': 'Fold into an inverted V with the hips high; lower head-first until the crown nearly touches the floor, then press up - front delts and rotator-cuff control. Common mistakes: the chest dropping into a regular push-up, elbows flaring.',
  '弹力带面拉': 'Anchor the band at face height; pull back to the forehead while rotating externally into two L shapes - a rotator-cuff warm-up and a fix for rounded posture. Common mistakes: tension so high the shoulders shrug, skipping the external rotation.',
  '杠铃弯举': 'Elbows pinned to the sides; curl the bar to the shoulders with the biceps and lower slowly on the way down. Common mistakes: swinging the lower back, elbows drifting forward into a press, half reps.',
  '哑铃锤式弯举': 'Neutral grip with the palms facing each other; curl along the sides to chest height - brachialis and forearms. Common mistakes: body English, collapsing the wrists.',
  '哑铃弯举': 'Supinated grip; curl to the shoulders with the elbows tight and squeeze the biceps hard at the top. Common mistakes: elbows wandering, heaving the weight up.',
  '绳索下压': 'Elbows pinned; press the cable down to full arm extension, optionally splaying the rope outward at the bottom for a deeper squeeze. Common mistakes: elbows flaring, pressing with body weight.',
  '哑铃颈后臂屈伸': 'Hold one dumbbell overhead with both hands, elbows pointing forward and fixed; lower behind the head until the triceps stretch, then extend. Common mistakes: elbows splaying, arching the back, dropping too fast.',
  '窄距卧推': 'Grip at shoulder width or slightly narrower; lower to the mid-lower chest line with the elbows tucked and press - triceps dominant. Common mistakes: gripping too narrow and straining the wrists, elbows flaring into a regular bench.',
  '弹力带弯举': 'Stand on the band and curl along the barbell path; tension peaks at the top so lower slowly. Common mistakes: leaning back, elbows drifting forward.',
  '凳上臂屈伸': 'Hands on a bench behind you; bend the elbows back to about 90 degrees and press up, legs straight or elevated on another bench for difficulty. Common mistakes: shoulders creeping up, hips set so far forward the shoulders ache.',
  '双杠臂屈伸': 'Body upright between the bars; bend the elbows behind you to about 90 degrees and press - triceps dominant. Common mistakes: leaning too far forward into chest territory, crashing into the bottom.',
  '负重双杠臂屈伸': 'Hang a plate from a belt or wear a dip belt, support yourself on the bars, lower to about 90 degrees of elbow bend and press up. Pick a load you can control for 5-8 clean reps. Common mistakes: loading too heavy and dipping so deep the shoulders ache, swinging the body for momentum.',
  '杠铃深蹲': 'Bar on the upper traps, brace hard; sit the hips and knees down until the thighs are parallel or below with the knees tracking the toes, then drive up through the heels. Common mistakes: knees caving in, rounding the back, weight shifting onto the toes.',
  '腿举（倒蹬机）': 'Back and hips pinned to the pad, feet shoulder width on the platform; lower to about 90 degrees of knee bend and press without locking out. Common mistakes: the lower back peeling off the pad, knees caving, descending too deep.',
  '保加利亚分腿蹲': 'Rear foot laced on a bench, front foot far enough forward; sink straight down until the front thigh is parallel with the load on the front leg. Common mistakes: sitting back onto the rear leg, the front knee caving, leaning the torso too far forward.',
  '哈克深蹲': 'Back flat against the pad with the shoulder pad on the traps; squat and stand along the rail - friendly to the lower back and easy to load. Common mistakes: feet set too far forward, locking out with a bounce.',
  '罗马尼亚硬拉': 'Stand tall with a soft knee bend; hinge the bar down the thighs until the hamstrings drum tight, then drive the hips through to stand, the bar glued to the body throughout. Common mistakes: squatting the weight down, the bar drifting off the legs, rounding the back.',
  '哑铃罗马尼亚硬拉': 'Dumbbells against the front of the thighs; hinge over until the hamstrings stretch clearly, back flat the whole way. Common mistakes: the dumbbells floating away from the body, snapping up through the lower back.',
  '腿屈伸（股四头）': 'Hook the ankles behind the roller; kick the legs to full extension with the quads, hold one second at the top, lower slowly. Common mistakes: kicking with momentum, hips lifting off the seat.',
  '腿弯举（腘绳肌）': 'Lie prone with the ankles under the roller; curl the heels toward the glutes and return slowly. Common mistakes: hiking the hips for leverage, half reps.',
  '站姿提踵': 'Balls of the feet on a step with the heels hanging; rise to the very top of the calf contraction, hold one second, lower to a full stretch. Common mistakes: bouncy fast reps, short range.',
  '杠铃臀桥': 'Lie back with a towel-padded bar across the hips; drive the hips up until the shoulders, hips and knees align and squeeze the glutes 1-2 seconds. Common mistakes: arching past neutral with the lower back, the hamstrings taking over.',
  '徒手深蹲': 'Feet shoulder width; sink the hips and knees to parallel with the arms raised for balance - the foundation pattern for beginners. Common mistakes: knees caving, heels lifting, rounding the back.',
  '哑铃高脚杯深蹲': 'Hold one dumbbell at the chest with the elbows tucked; squat until the elbows brush the inner thighs - the front-loaded weight keeps the torso upright. Common mistakes: the bell drifting off the body, heels rising.',
  '箭步蹲': 'Step one leg forward and lower until both knees reach about 90 degrees; drive back up with the front leg - stationary or walking. Common mistakes: the front knee shooting far past the toes, a tilting torso, the rear knee slamming down.',
  '臀桥': 'Lie back with the knees bent and feet planted; drive the hips up to a shoulders-hips-knees line and squeeze at the top. Common mistakes: over-lifting with the lower back, feet set too far away.',
  '单腿臀桥': 'One leg extended and hovering; complete the bridge on the other leg alone, matching both sides. Common mistakes: the pelvis tilting, twisting the back to steal range.',
  '靠墙静蹲': 'Slide down a wall until the thighs are parallel and the knees about 90 degrees and hold, with the knees tracking over the toes. Common mistakes: hands pushing the thighs for relief, stopping above parallel.',
  '平板支撑': 'Elbows under the shoulders, one line from head to heels; brace the core, glutes and legs together while keeping the breath. Common mistakes: sagging hips, piked hips, looking up.',
  '侧平板支撑': 'Side support with the elbow under the shoulder; lift the hips into a full-body line, on both sides. Common mistakes: hips sagging, tipping forward or back.',
  '卷腹': 'Lie back with the knees bent and the lower back glued down; curl the shoulder blades off the floor with the abs - no need to sit fully up. Common mistakes: yanking the neck, launching with momentum.',
  '悬垂举腿': 'Hang still from the bar; raise the legs with the lower abs (bent knees first, straight legs as you progress) and lower slowly to avoid swinging. Common mistakes: swinging the legs up, half range.',
  '俄罗斯转体': 'Sit leaning back about 45 degrees, feet down or floating; rotate side to side driven by the ribcage, the eyes following the hands. Common mistakes: only the arms wagging, collapsing the lower back.',
  '健腹轮': 'Kneel with the core braced; roll out to the furthest point you can control and pull back, keeping the abs engaged so the lower back never sags. Common mistakes: rolling too far and arching, dragging back with the shoulders.',
  '壶铃摆荡': 'Load the hips back like a hinge and snap them open to swing the bell to chest height - the arms stay loose ropes and never lift. Common mistakes: swinging with the lower back, squatting instead of hinging, swinging overhead into a press.',
  '哑铃农夫行走': 'Dumbbells hanging at the sides with the shoulder blades set and core braced; walk with short steady steps - grip and core in one. Common mistakes: shrugging, listing to one side, dragging the feet.',
  '箱跳': 'Jump with both feet onto a sturdy box; land soft, stand tall with the whole foot, then step down - never jump down. Common mistakes: a box too ambitious, knees caving on landing, jumping down and hammering the joints.',
  '深蹲跳': 'Drop to a half squat and explode upward; land with bent knees absorbing straight into the next rep. Common mistakes: landing stiff, knees caving.',
  '波比跳': 'Squat, plant the hands, shoot the legs back into a push-up, snap them in and jump vertically - a full-body cardio tool, so hold a steady pace. Common mistakes: hips sagging through the push-up, crash landings.',
  '登山跑': 'Shoulders stacked over the wrists; drive the knees to the chest in an alternating sprint while the hips stay level. Common mistakes: hips pitched too high, hands wandering back so the shoulders overload.',
  '熊爬': 'Crawl on hands and feet with the knees hovering about three centimeters, opposite hand and foot stepping together, back level. Common mistakes: hips too high, knees touching down.',
  '死虫式': 'Lie back with the lower back pressed flat; extend the opposite arm and leg slowly toward the floor and return, the waist never leaving the ground. Common mistakes: the back arching, moving too fast to stay controlled.',
  '鸟狗式': 'From all fours, extend the opposite arm and leg to a line with the torso and hold 2 seconds - anti-rotation for the core. Common mistakes: the back sagging, hips rotating, limbs lifting too high.',
  '哑铃单腿硬拉': 'Stand on one leg with a soft knee and the other reaching back; hinge over until the standing hamstring stretches, then drive the hip through to stand. Common mistakes: the hips rotating, snapping up through the lower back.',
  '药球砸地': 'Hold the ball overhead and slam it into the floor dead ahead with the whole core, hinging to follow. Common mistakes: throwing with the arms only, slanting the slam sideways.',
  '战绳（双甩）': 'A half-squat stance with the core braced; whip both arms together to send continuous waves down the ropes while breathing steadily. Common mistakes: standing tall and using only the arms, erratic rhythm.',
  '弹力带伐木': 'Anchor the band high or low at your side; pull diagonally from above one shoulder to the opposite hip with the torso rotating to lead the arms. Common mistakes: pulling with the arms only, letting the knees twist along.',
  '雪橇推': 'Lean into the sled in a diagonal line and push with short quick steps, driving through the whole foot. Common mistakes: pushing upright where you stall, strides too long.',
  '土耳其起立': 'Roll to an elbow, then the hand, kneel up and stand - eyes locked on the bell with the arm pressed straight throughout; master it empty before loading. Common mistakes: the bell drifting off the vertical line, rising with a rounded back.',
  '坐姿推胸（推胸机）': 'Seat set so the handles align with mid-chest, back flat on the pad; press horizontally to extension without lockout and return slowly. Common mistakes: a seat too high so it becomes a shoulder press, shoulders rolling forward off the pad.',
  '史密斯机卧推': 'Pinch the shoulder blades and lie back; lower along the rail to the mid-chest line and press without lockout - the fixed rail makes heavy pushes safer. Common mistakes: losing tightness by trusting the rail, bouncing off the bottom.',
  '哑铃地板卧推': 'Sit on the floor and roll back with the dumbbells; lower until the upper arms rest on the floor for a one-second pause, then press - a friendlier range for the shoulders and a strong top squeeze. Common mistakes: elbows slamming the floor, arching the lower back.',
  '器械划船': 'Chest against the pad; pull the handles to the belly with the elbows tight and squeeze the back at the finish. Common mistakes: rocking the torso back, shrugging.',
  '单臂绳索划船': 'One hand on the handle; retract the shoulder blade first, then bend the elbow to pull to the hip with the torso stable and square. Common mistakes: rotating the waist to heave, pulling to the chest.',
  '引体向上（反手）': 'An underhand grip at shoulder width brings the biceps in more; chin over the bar, everything else matches the overhand pull-up. Common mistakes: half reps, kicking.',
  '绳索侧平举': 'Set the pulley low; reach across the body for the far handle and raise it out to shoulder height - unbroken tension throughout. Common mistakes: an unstable stance, shrugging.',
  '哑铃耸肩': 'Dumbbells hanging at the sides; shrug straight up to the very top and hold one second - a longer, freer path than the barbell. Common mistakes: rolling the shoulders, bending the elbows.',
  '曲杠弯举（EZ杠）': 'The EZ-bar grips set the wrists at a friendlier angle; curl to the shoulders with the elbows tight - the first pick if the wrists complain. Common mistakes: swinging the waist.',
  '上斜哑铃弯举': 'Lean back on an incline bench so the arms hang behind; curl from that stretched position and squeeze at the top. Common mistakes: the elbows drifting forward, the shoulders taking over.',
  '绳索过顶臂屈伸': 'Back to a high pulley with the rope overhead; elbows forward and fixed, press the rope out and down to lockout with the triceps. Common mistakes: elbows splaying, pitching the torso onto the weight.',
  '仰卧杠铃臂屈伸': 'Lie back holding the bar over the forehead; upper arms vertical and frozen, bend the elbows to lower the bar behind the head and extend. Keep the load conservative and a spotter close. Common mistakes: upper arms drifting, the bar wandering toward the face.',
  '弹力带过顶臂屈伸': 'Stand on one end or anchor the band low behind you; grip overhead, lower behind the head and extend with the triceps. Common mistakes: elbows splaying, arching the back.',
  '相扑硬拉': 'A wide stance with the toes out and the arms inside the knees; the hips sit lower and the back stays more upright as the adductors and glutes drive the lockout - friendlier to the lower back. Common mistakes: knees caving hard, the bar drifting away.',
  '史密斯机深蹲': 'Bar on the traps with the feet slightly ahead of a free-squat stance; descend and stand along the vertical rail - less balance demand, good for pushing weight. Common mistakes: feet set too far back so the knees complain, arching with the rail as a crutch.',
  '哑铃箭步蹲': 'Hold the dumbbells at the sides for lunges; the lowered center of gravity makes balance and progressive loading easier. Common mistakes: steps too short so the knees jam, the torso pitching forward.',
  '腿外展（外展机）': 'Seated with the legs against the pads; open them outward until the hip-side muscles fully contract and return slowly. Common mistakes: loading so heavy the torso leans back, bouncing open with momentum.',
  '腿内收（内收机）': 'Seated with the pads on the insides of the knees; draw the legs together until the inner thighs contract and return slowly. Common mistakes: heaving with heavy stacks, twisting at the waist.',
  '弹力带侧向走': 'Band above the ankles; stay in a half squat with tension as you sidestep, the knees tracking the toes the whole way. Common mistakes: standing too upright, knees caving.',
  '仰卧举腿': 'Lie back with the legs straight and together; raise them toward vertical with the lower abs and lower slowly to just above the floor. Common mistakes: the lower back arching up, free-falling on the descent.',
  '空中蹬车': 'Lie back and alternate opposite elbow to knee with the other leg extended and floating; the rotation matters more than the height. Common mistakes: pulling on the head, the extended leg dropping too low and loading the back.',
  '跳绳': 'Turn the rope with the wrists and hop lightly on the forefeet with soft knees; rhythm beats height. Common mistakes: circling with whole arms, jumping too high and constantly catching the feet.',
  // ===== 第三弹 36 条 =====
  '下斜杠铃卧推': 'Hook the feet on the decline bench; lower the bar to the mid-lower chest and press along a slightly back-and-up path - lower-chest dominant. Common mistakes: sliding toward the head, the bar drifting to the neck.',
  '哑铃上斜飞鸟': 'Lie back on the incline bench with a fixed slight elbow bend; open the dumbbells in an arc until the upper chest fully stretches, then close them. Common mistakes: the elbow angle changing into a press, dropping too deep and loading the shoulders.',
  '史密斯机上斜卧推': 'Incline setup under the Smith rail; press along the fixed track with the shoulder blades pinched throughout - with balance handled, deliberately slow the descent. Common mistakes: hips sliding off the bench, bouncing the bottom.',
  '绳索上斜夹胸': 'Set the pulleys low; lie back on the incline bench and sweep the cables up and together from both sides to above the chest. Common mistakes: bending the elbows into a press, the shoulder blades riding up.',
  '哑铃窄距卧推': 'Dumbbells together over the mid-chest line; press through a narrow path so the inner chest and triceps share the work. Common mistakes: elbows flaring wide, the bells clanging and destabilizing at the top.',
  '早安式': 'Bar on the upper traps; hinge over until the upper back nears parallel with the floor and stand back up by driving the hips - hamstrings and lower back braced the whole way. Keep the load humble. Common mistakes: bending the knees into a squat, rounding the back, chasing weight.',
  'V把下拉': 'Pull the narrow V-bar down to the collarbone with the elbows tracking vertically and tight - lower and outer lats. Common mistakes: leaning far back into a row.',
  '窄距高位下拉': 'A narrow grip pulled to the upper chest with the elbows traveling along the sides - a longer range than the wide grip. Common mistakes: half reps, biceps taking over.',
  '反握杠铃划船': 'Hinge to about 45 degrees and row with an underhand grip along the body to the lower belly - great for the lower lats. Common mistakes: rounding the back, heaving with momentum.',
  '哑铃双臂俯身划船': 'Hinge over and row both dumbbells to the hips with the elbows tight, squeezing the back at the top. Common mistakes: shrugging, the torso bouncing for leverage.',
  '仰卧杠铃上拉': 'Upper back across a bench; with a fixed bent-arm angle, sweep the bar from behind the head back over the chest in an arc - lats and chest. Common mistakes: the elbow angle collapsing into an extension, the hips sagging.',
  '反手高位下拉': 'An underhand, shoulder-width grip pulled to just above the collarbone - the biceps help, beginner friendly. Common mistakes: leaning back too far, half reps.',
  '坐姿杠铃推举': 'Seated, press the bar from the collarbone overhead to ear height with the core braced and the lower back flat. Common mistakes: over-arching into extension, elbows flaring.',
  '直立划船': 'A narrow grip dragging the bar up the body to chin height with the elbows always above the hands - side delts and traps. Skip or switch to a wide rope grip if the shoulders complain. Common mistakes: the bar drifting off the body, shrugging to compensate, pulling too high.',
  '绳索反向飞鸟': 'Two pulleys set to cross; grab the opposite handles and open the arms backward and out with constant rear-delt tension. Common mistakes: the lats rowing instead, going too heavy.',
  '单臂哑铃推举': 'A single-side press with the core resisting side-bend and the pelvis square - match both sides. Common mistakes: tilting the torso for leverage.',
  '集中弯举': 'Seated with the elbow braced against the inner thigh; curl alone with one arm and squeeze the biceps hard at the top. Common mistakes: swinging the arm, leaning back.',
  '反握杠铃弯举': 'A palms-down reverse grip curling the bar - forearm extensors and brachialis, a make-up move for a weak grip. Keep it light. Common mistakes: chasing weight until the wrists ache, swinging.',
  '绳索锤式弯举': 'A neutral rope-handle hammer curl - brachialis and forearms under unbroken tension. Common mistakes: the elbows drifting forward.',
  'V把下压': 'Press the V-bar down to full extension - the outer triceps head, squeeze one second at the bottom. Common mistakes: elbows flaring, pressing with body weight.',
  '仰卧哑铃臂屈伸': 'Lie back holding dumbbells over the forehead; upper arms vertical and frozen, lower behind the head and extend. Common mistakes: the upper arms swinging, dropping too fast.',
  '哑铃后踢': 'Hinged over with the elbow fixed and high; kick the dumbbell back and up to full triceps extension and squeeze one second. Common mistakes: swinging, short range.',
  '上斜哑铃锤式弯举': 'Lean back on the incline so the arms hang behind; hammer-curl from that stretched position - deep brachialis stimulus. Common mistakes: elbows traveling forward, shoulders taking over.',
  '直腿硬拉': 'Knees nearly locked with only a soft bend; hinge the bar down the legs to the hamstring limit and drive the hips to stand - a stricter knee angle than the RDL, so go lighter. Common mistakes: rounding the back, the bar leaving the legs.',
  '相扑哑铃深蹲': 'A wide stance with the toes out, one dumbbell hanging between the legs; squat straight down - inner thighs and glutes. Common mistakes: knees caving, heels lifting.',
  '杠铃箭步蹲': 'Lunges with the bar on the upper traps - stable loading that suits progressive work. Common mistakes: steps too short so the knees jam, the torso pitching forward.',
  '坐姿腿弯举': 'The seated leg curl - a hip angle that complements the lying version for different hamstring segments. Common mistakes: hips lifting off the pad, half reps.',
  '驴式提踵': 'Hinge over so the calves work from a stretched position; a machine pad or partner secures the hips. Common mistakes: bouncy fast reps, short range.',
  '箱式深蹲': 'Squat onto a sturdy box top, pause a beat, then stand - hip-extension strength and bottom-position confidence. Common mistakes: relaxing and rounding once seated.',
  '仰卧起坐': 'Lie back with the knees bent; curl the torso up with the abs until the chest nears the thighs and lower slowly. Switch to crunches if the lower back complains. Common mistakes: yanking the neck, pinned feet turning it into a hip swing.',
  '侧卷腹': 'Lie back with the knees tipped to one side; draw the same-side ribs toward the hip with the obliques - match both sides. Common mistakes: pulling the neck, rotating on momentum.',
  '健身球卷腹': 'Crunch lying back on a stability ball - the unstable surface wakes the deep core. Common mistakes: slipping around on the ball, the neck doing the work.',
  'V字两头起': 'Raise the arms and legs together until the hands meet the feet in a V, then lower slowly - the whole rectus. Common mistakes: swinging only the legs, the lower back slamming down.',
  '器械卷腹': 'On the crunch machine, curl the ribcage toward the pelvis with a slow return. Common mistakes: hips rocking for momentum, a stack so heavy it swings.',
  '借力推': 'Dip into a small knee bend and drive the legs to punch the bar overhead in one shot - full-body power; the leg drive and press land together. Common mistakes: splitting it into a squat then a press, heels lifting as you drive.',
  '壶铃单臂划船': 'Hinged over, drag the kettlebell to the hip with the elbow brushing the ribs. Common mistakes: twisting the torso for leverage, pulling to the chest.',
  '阿诺德推举': 'Seated with back support, hold a dumbbell in each hand at chest height, palms facing you; rotate the wrists to palms-forward as you press up and rotate back on the way down. Keep elbows slightly in front of the body, forearms vertical, low back on the pad. Common mistakes: going too heavy so the rotation gets cut short, turning it into a swing.',
  '牧师凳弯举': 'Press your upper arms and armpits into the pad with elbows fixed; only the forearms curl. Pause at the top, lower slowly to feel the stretch, keep a slight bend. Common mistakes: shrugging or lifting the elbows off the pad to cheat.',
  '哑铃仰卧上拉': 'Lie with your upper back across a flat bench, feet planted; hold one dumbbell by one end over your chest. Keep a fixed slight elbow bend; lower the dumbbell in an arc behind your head until chest and lats stretch, then pull it back along the same arc. Common mistakes: the elbow angle opening into a triceps extension, or going too deep and straining the shoulders.',
  '山羊挺身': 'Hips on the pad of a Roman-chair bench, ankles hooked, arms crossed; hinge down until your torso is about parallel to the floor, then raise back up only to a straight line with your legs. Do not hyperextend the lower back or swing; stay slow and controlled. Hold a plate to add load.',
  '反向划船': 'Set a bar at about waist height (or use a sturdy table), body straight from head to heels, heels on the floor, grip slightly wider than shoulders. Retract and depress the shoulder blades first, then pull your chest to the bar and pause one second. Common mistakes: sagging hips, reaching with the chin, pulling only with the arms. Raise the bar to make it easier.',
  '登阶': 'Use a bench or step about knee height; place your whole foot on it and drive up with the front leg glutes and thighs. The trailing leg only taps for balance - do not push off. Lower slowly under control from the front leg. Common mistakes: leaning the torso too far forward, or kicking hard with the rear leg. Hold dumbbells to add load.',
  '坐姿提踵': 'Sit on the seated calf machine with knees bent about 90 degrees, balls of the feet on the platform, pad pressed on the knees. Lower the heels to a full calf stretch, then rise to the top and hold 1-2 seconds. The bent-knee position targets the deep soleus. Common mistakes: partial range and bobbing with momentum.',
  '北欧腿弯举': 'Kneel with ankles anchored by a partner or under a sofa; keep hips-to-shoulders in one line as you lower forward slowly. Pull yourself back up only with the hamstrings; push lightly off the floor with your hands to assist at first. The slower the lowering, the better. Common mistakes: breaking at the hips, chasing full range too soon - start half-range or with band assistance.',
  '绳索卷腹': 'Kneel facing a high pulley, rope held at the sides of your head, hips fixed. Curl the ribs toward the pelvis with the abs, elbows traveling toward the knees, spine rounding at the top. Common mistake: bowing the whole torso down flat - that is the hips moving, not the abs crunching.',
  '弹力带肩外旋': 'Pin your upper arm to your side with the elbow bent 90 degrees, holding one end of a band; rotate the forearm outward like opening a door, keeping the elbow glued to your side as the band pulls in. A rotator-cuff maintenance move - keep it light, 15-20 reps. Common mistakes: the elbow drifting out, the torso rotating to compensate.',
  '蝴蝶机反向飞鸟（后束）': 'Sit with the chest firmly against the pad, shoulders down; hold the handles and sweep the arms back and out, led by the elbows. Squeeze one second at the end range, return slowly, weight controlled throughout. Common mistakes: shrugging so the traps take over, swinging through an oversized range.',
  '帕洛夫推举': 'Stand sideways to a cable stack (band anchor at home), hold the handle pulled to your chest and feel the anti-rotation tension in the obliques. Exhale, press the arms straight out, hold 2-3 seconds, return slowly; do both sides. Common mistakes: getting rotated by the weight, holding the breath or letting the lower back arch as you press.',
  '反向卷腹': 'Lie on your back with knees bent and lower back flat on the floor. Curl the pelvis toward the ribs and draw the knees to the chest using the lower abs - do not swing the legs. Lower slowly, keeping the lower back down the whole time. Common mistake: leg-swing momentum turning it into a leg raise.',
  '哑铃侧屈': 'Stand tall holding a dumbbell in one hand, other hand behind your head. Bend sideways toward the weighted side, then straighten using the obliques on the opposite side, pelvis stable. Pure lateral fold - no leaning forward or back. Common mistakes: bobbing with momentum, a too-heavy bell turning it into a shrug.',
  '颈前深蹲': 'Rest the bar on the front delts and collarbone, elbows high and pointing forward near parallel to the floor; brace the core and squat with an upright torso to at least thigh-parallel. Common mistakes: elbows dropping so the bar rolls forward, the torso pitching. If wrist or shoulder mobility is lacking, transition via goblet squats.',
  '杠铃臀推': 'Upper back against a bench, padded barbell over the hips, feet flat. Drive through the heels until shoulders, hips and knees form a straight line; squeeze the glutes 1-2 seconds at the top, lower under control. Common mistakes: overextending into a lower-back arch at the top, bouncing with momentum.',
  // 补库第四弹（2026-09-29 臀腿+商业健身房器械）
  '绳索髋屈伸': 'Set a cable pulley to the lowest position, face away from the stack and hold the rope between your legs. Hinge at the hips, then drive them forward to stand tall against the cable, squeezing the glutes one second at the top; targets glutes and hamstrings. Common mistakes: hyperextending the lower back instead of driving with the hips, standing too far from the machine so tension dies.',
  '绳索单腿后踢': 'Cuff a cable to one ankle, hold the frame and lean forward slightly. Kick that leg straight back and up until the glute fully contracts, then return slowly; switch sides when done. Common mistakes: kicking too high so the lower back takes over, wavering on the support leg.',
  '跪姿后踢腿': 'On all fours with hands under shoulders, keep one knee bent 90 degrees and drive the heel toward the ceiling, stopping as soon as the glute is tight - height is not the goal. Common mistakes: sagging the lower back to fake range, tilting the pelvis, rushing the reps.',
  '弹力带髋伸展': 'Anchor a band behind you at a low point (or stand on one end), loop the other end around your hip or ankle. Drive the hips forward against the pull until standing tall and squeeze the glute at the top. Common mistakes: unstable stance, arching the lower back to finish the range.',
  '跪姿杠铃蹲': 'Kneel with shins flat on the floor and a barbell across your shoulders (inside a rack with safety pins set). Sit the hips back and down toward the heels, then drive up through the glutes to tall-kneel; a very isolated glute move - keep loads conservative. Common mistakes: leaning the torso back, feet not pinned down so you cannot sit back.',
  '站姿腿弯举': 'On a standing leg curl machine, place the roller above the heel of the working leg, hold the handles, and curl the heel toward your glute before lowering slowly; one leg at a time. Common mistakes: leaning the body forward to cheat, swinging the stack with momentum.',
  '单腿腿屈伸': 'On a leg extension machine, work one leg at a time: extend fully, pause one second at the top, lower slowly - the go-to fix for side-to-side strength gaps. Common mistakes: lifting the hips off the seat, letting the weight bounce back up.',
  '倒蹬机提踵': 'In a leg press, place only the balls of your feet on the lower edge of the platform, knees locked straight, and press through a full calf range; the reclined angle lets you pile on weight. Common mistakes: bending the knees to cheat, bouncing at the bottom.',
  '史密斯机提踵': 'Stand under a Smith machine bar with the balls of your feet planted, bar on your shoulders. Lower the heels to a full stretch, then press up to the very top; the fixed rail means zero balance demand - pure calf work. Common mistakes: cutting the range short, bending the knees to cheat.',
  '框架硬拉机': 'On a leverage deadlift machine, take the neutral handles from a hinged start and drive the hips to stand tall, squeezing the glutes at the top. The fixed path removes the balance demand of a barbell deadlift - great for loading the posterior chain heavy and safe. Common mistakes: arching the lower back at the top, dropping the weight stack on the way down.',
  '臀腘绳挺身（GHD）': 'Set ankles under the pads of a glute-ham developer, start kneeling tall, and lower your torso slowly until near horizontal, then pull yourself back up with the glutes and hamstrings. Start with half range if strength is not there yet. Common mistakes: hyperextending the lumbar spine instead of driving with the hips, dropping too fast.',
  '反向山羊挺身': 'Lie prone on a reverse hyperextension bench with legs hanging. Swing both legs back and up until they line up with your torso, driven by the glutes and hamstrings, then return slowly; easy on the lower back, great for the posterior chain. Common mistakes: overarching at the top, swinging on momentum.',
  '俯卧T杠划船': 'Chest and abdomen prone on a T-bar row bench, row the handle toward your chest with both arms and retract the shoulder blades fully at the top; the pinned torso leaves no room to cheat. Common mistakes: half range, head lifting off the pad.',
  '高位划船机': 'Sit at a leverage high-row machine with the handles high; pull them toward your collarbone with elbows driving out and back, hitting the upper back and rear delts. Common mistakes: rocking the torso for leverage, pulling only half way.',
  '坐姿推肩机': 'Back firmly on the pad, press the handles from ear height up along the fixed track until the arms are nearly straight; no balance to fight, so focus on feeling the delts work. Common mistakes: shrugging the traps, stopping short of full extension.',
  '耸肩机': 'On a shrug machine with handles at your sides, shrug both shoulders straight up toward the ears, hold one second at the top and lower slowly; the fixed path lets you load heavy safely. Common mistakes: rolling the shoulders, bending the elbows to lift.',
  '器械弯举': 'On a bicep curl machine with arms locked on the pad, curl to the top and squeeze; the pad stops the elbows from drifting forward, making it highly isolated. Common mistakes: hips lifting off the seat, letting the weight stack slam down.',
  '坐姿臂屈伸机': 'On a seated triceps extension machine, keep the upper arms firmly on the pads and press the forearms down to full lockout, pausing one second; elbow-friendly and very isolated. Common mistakes: elbows lifting off the pads, pressing the body down instead of the arms.',
  '上斜推胸机': 'An incline chest press machine: back on the pad, press the handles up and together along the fixed track, focusing on the upper chest. Common mistakes: shoulders shrugging up, lazily stopping short of the top.',

  '弹力带深蹲': 'Stand on both ends of a band and bring it up to your shoulders; squat until thighs are near parallel, then drive up. Band tension grows as you descend - keep the torso tall throughout. Common mistakes: the band slipping under the feet, knees caving in.',
  '弹力带早安式': 'Step on the band and loop it over your shoulders and upper back; hinge at the hips until your torso nears parallel, then drive the hips to stand tall - hits hamstrings and glutes. Common mistakes: rounding the back, bending the knees into a squat.',
  '弹力带卧推': 'Anchor the band behind a bench (or loop it across your back), press both ends to full arm extension and lower slowly; tension rises through the press, a nice complement to barbell pressing. Common mistakes: letting the band slack off, elbows flaring.',
  '弹力带推肩': 'Stand on the band, pull the ends to shoulder height, and press straight overhead to lockout; brace the core, no lower-back arch. Common mistakes: shrugging to cheat, the pressing path wandering back and forth.',
  '弹力带臂屈伸': 'Anchor a band high (door frame or pull-up bar), grip both ends behind your head and extend the arms straight up - an overhead triceps move; keep the elbows fixed and let only the forearms move. Common mistakes: elbows flaring, sinking the body to cheat.',
  '弹力带提踵': 'Stand with the balls of your feet on the band (or stand on one end and pull the other to your shoulders); lower the heels to a full stretch, then rise to the very top, slow both ways. Common mistakes: short range, bouncing reps.',
  '弹力带臀桥': "Loop a band just above your knees and lie back with feet flat. Drive the hips up until shoulders-hips-knees line up, actively squeezing against the band's outward pull for one second at the top. Common mistakes: arching too high, pushing through the feet instead of the glutes.",
  '弹力带直立划船': 'Stand on the band with a narrow grip and pull it up your body to chin height, elbows leading above the hands, lower slowly. Shrink the range or skip it if shoulders complain. Common mistakes: the band drifting away from the body, shrugging to compensate.',
  '俯卧背挺身': 'Lie face down on the floor (or with hips on a bed edge), hands lightly at the ears, and raise the torso using the glutes and lower back to a natural height before lowering slowly - small range, full control. Common mistakes: craning the neck up, snapping up with momentum.',
  '哑铃交替平举': 'With a dumbbell in each hand, raise one arm forward to shoulder height while the other goes out to the side, alternating; keep the torso still. Common mistakes: swinging the weights up, shrugging.',
};

/// 动作名显示（动作库/训练/历史/统计等处）。
String exname(String zh) => Lang.isEn ? (_kExerciseEn[zh] ?? zh) : zh;

/// 库内置名词（模板名/训练日标题等）显示。
String dname(String zh) => Lang.isEn ? (_kPresetNounEn[zh] ?? zh) : zh;

/// 肌群名显示。
String mname(String zh) => Lang.isEn ? (_kMuscleEn[zh] ?? zh) : zh;

/// 器械场景显示。
String eqname(String zh) => Lang.isEn ? (_kEquipmentEn[zh] ?? zh) : zh;

/// 细分器械显示（ExerciseMeta.gear）。
String gearname(String zh) => Lang.isEn ? (_kGearEn[zh] ?? zh) : zh;

/// 动作要点显示（按动作名映射英译，映射不到回落中文）。
String cuen(String name, String zh) => Lang.isEn ? (_kCueEn[name] ?? zh) : zh;

/// 疼痛部位显示（P2-B）：数据键是中文（PainArea.*），英文界面译成英文。
/// 映射不到的自定义部位原样显示中文（与动作名同一策略）。
String painname(String zh) => switch (zh) {
      '肩' => tx('肩', en: 'Shoulder'),
      '肘' => tx('肘', en: 'Elbow'),
      '腰' => tx('腰', en: 'Lower back'),
      '膝' => tx('膝', en: 'Knee'),
      '踝' => tx('踝', en: 'Ankle'),
      '其他' => tx('其他', en: 'Other'),
      _ => zh,
    };
